  <meta property="twitter:description" content="A global creative agency fusing design, strategy, and technology across 30+ studios worldwide.">
  <meta property="twitter:image" content="https://www.leapstudio.com/og-image.jpg">

  <!-- Structured Data -->
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "ProfessionalService",
