    "areaServed": [
      {"@type": "Country", "name": "United States"},
      {"@type": "Country", "name": "United Kingdom"},
      {"@type": "Country", "name": "Germany"},
      {"@type": "Country", "name": "Singapore"},
      {"@type": "Country", "name": "Australia"},
      {"@type": "Country", "name": "India"}
    ],
    "sameAs": [
      "https://www.linkedin.com/company/leap-studio",
      "https://www.instagram.com/leapstudio"
    ]
  }
  </script>

  <style>
    /* ===== RESET & BASE ===== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg: #0A0A0A;
      --bg-1: #111111;
      --bg-2: #181818;
      --bg-card: #141414;
      --border: rgba(255,255,255,0.08);
      --border-hover: rgba(255,255,255,0.18);
      --white: #FFFFFF;
      --gray-100: #F5F5F5;
      --gray-300: #BBBBBB;
      --gray-500: #808080;
      --gray-700: #3A3A3A;
      --accent: #3B82F6;
      --accent-hover: #60A5FA;
      --amber: #F59E0B;
      --font: 'Inter', 'Neue Haas Grotesk', 'Helvetica Neue', Arial, sans-serif;
      --radius: 4px;
      --radius-lg: 8px;
      --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; font-size: 16px; }

    body {
      background-color: var(--bg);
      color: var(--white);
      font-family: var(--font);
      line-height: 1.6;
      overflow-x: hidden;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; border: none; background: none; font-family: var(--font); }

    /* ===== TYPOGRAPHY ===== */
    .label {
      font-size: 0.7rem;
      font-weight: 600;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--gray-500);
    }

    .section-title {
      font-size: clamp(2rem, 5vw, 3.5rem);
      font-weight: 700;
      line-height: 1.1;
      letter-spacing: -0.02em;
    }

    .section-subtitle {
      font-size: 1.0625rem;
      color: var(--gray-300);
      max-width: 540px;
      margin-top: 0.75rem;
      line-height: 1.65;
    }

    /* ===== LAYOUT ===== */
    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 clamp(1.25rem, 4vw, 3rem);
    }

    .section {
      padding: clamp(4rem, 8vw, 7rem) 0;
    }

    .section-header {
      margin-bottom: 3rem;
    }

    /* ===== BUTTONS ===== */
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.75rem 1.5rem;
      font-size: 0.875rem;
      font-weight: 600;
      letter-spacing: 0.02em;
      border-radius: var(--radius);
      transition: var(--transition);
      cursor: pointer;
    }

    .btn-primary {
      background: var(--white);
      color: var(--bg);
    }
    .btn-primary:hover { background: var(--gray-100); transform: translateY(-1px); }

    .btn-outline {
      border: 1px solid var(--border-hover);
      color: var(--white);
    }
    .btn-outline:hover { border-color: var(--white); background: rgba(255,255,255,0.05); }

    .btn-ghost {
      color: var(--white);
      padding: 0;
      font-size: 0.875rem;
      font-weight: 500;
    }
    .btn-ghost:hover { color: var(--accent); }

    .btn-ghost .arrow {
      display: inline-block;
      transition: transform var(--transition);
    }
    .btn-ghost:hover .arrow { transform: translateX(4px); }

    .btn-accent {
      background: var(--accent);
      color: var(--white);
    }
    .btn-accent:hover { background: var(--accent-hover); transform: translateY(-1px); }

    /* ===== NAVIGATION ===== */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      background: rgba(10,10,10,0.85);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border-bottom: 1px solid var(--border);
      transition: var(--transition);
    }

    .nav-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 clamp(1.25rem, 4vw, 3rem);
    }

    .nav-logo {
      font-size: 1.25rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      color: var(--white);
      flex-shrink: 0;
    }
    .nav-logo span { color: var(--accent); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: clamp(1rem, 2.5vw, 2rem);
      list-style: none;
    }

    .nav-links a {
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--gray-300);
      letter-spacing: 0.01em;
      transition: color var(--transition);
    }
    .nav-links a:hover { color: var(--white); }

    .nav-right {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    /* Language Selector */
    .lang-selector {
      position: relative;
    }

    .lang-btn {
      display: flex;
      align-items: center;
      gap: 0.375rem;
      font-size: 0.8rem;
      font-weight: 500;
      color: var(--gray-300);
      padding: 0.375rem 0.625rem;
      border: 1px solid var(--border);
      border-radius: var(--radius);
      transition: var(--transition);
    }
    .lang-btn:hover { color: var(--white); border-color: var(--border-hover); }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      background: var(--bg-2);
      border: 1px solid var(--border-hover);
      border-radius: var(--radius-lg);
      overflow: hidden;
      min-width: 148px;
      opacity: 0;
      pointer-events: none;
      transform: translateY(-8px);
      transition: opacity var(--transition), transform var(--transition);
      z-index: 200;
    }
    .lang-dropdown.open {
      opacity: 1;
      pointer-events: all;
      transform: translateY(0);
    }

    .lang-option {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0.75rem 1rem;
      font-size: 0.8125rem;
      color: var(--gray-300);
      cursor: pointer;
      transition: background var(--transition);
      border: none;
      background: none;
      width: 100%;
      font-family: var(--font);
    }
    .lang-option:hover { background: rgba(255,255,255,0.05); color: var(--white); }
    .lang-option.active { color: var(--white); }

    .nav-contact-btn {
      font-size: 0.8125rem;
      font-weight: 600;
      padding: 0.5rem 1.125rem;
      background: var(--white);
      color: var(--bg);
      border-radius: var(--radius);
      transition: var(--transition);
    }
    .nav-contact-btn:hover { background: var(--gray-100); }

    /* Hamburger */
    .nav-hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      padding: 0.5rem;
    }
    .nav-hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--white);
      border-radius: 2px;
      transition: var(--transition);
    }
    .nav-hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .nav-hamburger.open span:nth-child(2) { opacity: 0; }
    .nav-hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    .nav-mobile {
      display: none;
      flex-direction: column;
      gap: 0;
      background: var(--bg-1);
      border-top: 1px solid var(--border);
      padding: 1rem 0;
    }
    .nav-mobile.open { display: flex; }
    .nav-mobile a {
      padding: 0.875rem clamp(1.25rem, 4vw, 3rem);
      font-size: 0.9375rem;
      font-weight: 500;
      color: var(--gray-300);
      border-bottom: 1px solid var(--border);
      transition: color var(--transition);
    }
    .nav-mobile a:hover { color: var(--white); }

    /* ===== HERO SECTION ===== */
    #hero {
      position: relative;
      height: 100vh;
      min-height: 600px;
      display: flex;
      align-items: flex-end;
      overflow: hidden;
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      z-index: 0;
    }

    .hero-slide {
      position: absolute;
      inset: 0;
      opacity: 0;
      transition: opacity 0.8s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .hero-slide.active { opacity: 1; }

    .hero-slide-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
    }

    .hero-slide:nth-child(1) .hero-slide-bg {
      background: linear-gradient(135deg, #0A1628 0%, #0F2444 40%, #071018 100%);
    }
    .hero-slide:nth-child(2) .hero-slide-bg {
      background: linear-gradient(135deg, #0D1117 0%, #1A0A2E 50%, #0A0A14 100%);
    }
    .hero-slide:nth-child(3) .hero-slide-bg {
      background: linear-gradient(135deg, #071A14 0%, #0D2B1F 50%, #0A0A0A 100%);
    }
    .hero-slide:nth-child(4) .hero-slide-bg {
      background: linear-gradient(135deg, #1A0E00 0%, #2B1A00 50%, #0A0A0A 100%);
    }
    .hero-slide:nth-child(5) .hero-slide-bg {
      background: linear-gradient(135deg, #100A24 0%, #1C1040 50%, #0A0A0A 100%);
    }

    .hero-grain {
      position: absolute;
      inset: 0;
      opacity: 0.04;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
      background-size: 256px 256px;
    }

    .hero-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.85) 0%, rgba(0,0,0,0.3) 50%, rgba(0,0,0,0.1) 100%);
    }

    .hero-content {
      position: relative;
      z-index: 2;
      width: 100%;
      padding-bottom: clamp(3rem, 6vw, 5rem);
    }

    .hero-inner {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 clamp(1.25rem, 4vw, 3rem);
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 2rem;
    }

    .hero-text {
      max-width: 680px;
    }

    .hero-tag {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      margin-bottom: 1.25rem;
      font-size: 0.75rem;
      font-weight: 600;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--accent);
    }
    .hero-tag::before {
      content: '';
      display: block;
      width: 24px;
      height: 1px;
      background: var(--accent);
    }

    .hero-title {
      font-size: clamp(2.5rem, 6vw, 4.5rem);
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -0.03em;
      margin-bottom: 1.25rem;
    }

    .hero-body {
      font-size: clamp(1rem, 1.5vw, 1.125rem);
      color: rgba(255,255,255,0.75);
      max-width: 520px;
      margin-bottom: 2rem;
      line-height: 1.7;
    }

    .hero-controls {
      display: flex;
      align-items: center;
      gap: 0;
    }

    .hero-dots {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0.5rem;
      margin-left: 2rem;
    }

    .hero-dot {
      width: 3px;
      height: 20px;
      border-radius: 2px;
      background: rgba(255,255,255,0.25);
      transition: var(--transition);
      cursor: pointer;
      border: none;
    }
    .hero-dot.active {
      background: var(--white);
      height: 40px;
    }
    .hero-dot:hover { background: rgba(255,255,255,0.6); }

    .hero-nav-btns {
      display: flex;
      gap: 0.5rem;
      margin-left: 1.5rem;
    }

    .hero-nav-btn {
      width: 44px;
      height: 44px;
      border: 1px solid var(--border-hover);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 1.125rem;
      transition: var(--transition);
    }
    .hero-nav-btn:hover { background: rgba(255,255,255,0.1); border-color: var(--white); }

    /* ===== TEAM SECTION ===== */
    #team {
      background: var(--bg-1);
      padding: clamp(4rem, 8vw, 7rem) 0;
    }

    .region-tabs {
      display: flex;
      gap: 0;
      margin-top: 2.5rem;
      border-bottom: 1px solid var(--border);
      overflow-x: auto;
      scrollbar-width: none;
    }
    .region-tabs::-webkit-scrollbar { display: none; }

    .region-tab {
      padding: 0.75rem 1.5rem;
      font-size: 0.875rem;
      font-weight: 600;
      color: var(--gray-500);
      border-bottom: 2px solid transparent;
      margin-bottom: -1px;
      transition: var(--transition);
      white-space: nowrap;
      cursor: pointer;
      letter-spacing: 0.02em;
    }
    .region-tab:hover { color: var(--gray-300); }
    .region-tab.active {
      color: var(--white);
      border-bottom-color: var(--white);
    }

    .team-region {
      display: none;
    }
    .team-region.active { display: block; }

    .team-carousel-wrapper {
      position: relative;
      margin-top: 2.5rem;
      overflow: hidden;
    }

    .team-track {
      display: flex;
      gap: 1.5rem;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      will-change: transform;
    }

    .team-card {
      flex-shrink: 0;
      width: calc((100% - 3rem) / 3);
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: border-color var(--transition), transform var(--transition);
    }
    .team-card:hover {
      border-color: var(--border-hover);
      transform: translateY(-4px);
    }

    .team-card-photo {
      width: 100%;
      aspect-ratio: 4/3;
      overflow: hidden;
      background: var(--bg-2);
      position: relative;
    }

    .team-card-photo-placeholder {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      color: var(--gray-700);
    }

    .team-card-body {
      padding: 1.5rem;
    }

    .team-card-quote {
      font-size: 0.9375rem;
      line-height: 1.65;
      color: var(--gray-300);
      font-style: italic;
      margin-bottom: 1.5rem;
    }

    .team-card-info {
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
      margin-bottom: 1.25rem;
    }

    .team-card-name {
      font-size: 1rem;
      font-weight: 700;
      color: var(--white);
    }

    .team-card-role {
      font-size: 0.8125rem;
      color: var(--gray-500);
    }

    .team-card-location {
      display: flex;
      align-items: center;
      gap: 0.375rem;
      font-size: 0.8125rem;
      color: var(--gray-500);
    }

    .team-card-cta {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      display: flex;
      align-items: center;
      gap: 0.25rem;
      transition: color var(--transition);
    }
    .team-card-cta:hover { color: var(--accent-hover); }

    .team-carousel-controls {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-top: 2rem;
    }

    .carousel-nav-btns {
      display: flex;
      gap: 0.5rem;
    }

    .carousel-btn {
      width: 40px;
      height: 40px;
      border: 1px solid var(--border-hover);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      transition: var(--transition);
    }
    .carousel-btn:hover { background: rgba(255,255,255,0.08); }
    .carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }

    .carousel-progress {
      display: flex;
      gap: 6px;
    }

    .progress-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--gray-700);
      transition: var(--transition);
      cursor: pointer;
    }
    .progress-dot.active { background: var(--white); width: 20px; border-radius: 3px; }

    /* ===== WORK SECTION ===== */
    #work {
      padding: clamp(4rem, 8vw, 7rem) 0;
    }

    .work-carousel-wrapper {
      position: relative;
      overflow: hidden;
      margin-top: 2.5rem;
    }

    .work-track {
      display: flex;
      gap: 1.5rem;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      will-change: transform;
    }

    .work-card {
      flex-shrink: 0;
      width: calc((100% - 3rem) / 2.5);
      min-width: 320px;
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: border-color var(--transition), transform var(--transition);
      cursor: pointer;
    }
    .work-card:hover {
      border-color: var(--border-hover);
      transform: translateY(-4px);
    }

    .work-card-image {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--bg-2);
      position: relative;
      overflow: hidden;
    }

    .work-card-image-inner {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .work-card-image-label {
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: rgba(255,255,255,0.2);
    }

    .work-card-1 .work-card-image { background: linear-gradient(135deg, #1A2B1A, #0D1F0D); }
    .work-card-2 .work-card-image { background: linear-gradient(135deg, #1A1A2B, #0D0D1F); }
    .work-card-3 .work-card-image { background: linear-gradient(135deg, #2B1A0D, #1F120A); }
    .work-card-4 .work-card-image { background: linear-gradient(135deg, #1A2B2B, #0D1F1F); }
    .work-card-5 .work-card-image { background: linear-gradient(135deg, #2B2B1A, #1F1F0D); }
    .work-card-6 .work-card-image { background: linear-gradient(135deg, #2B1A2B, #1F0D1F); }
    .work-card-7 .work-card-image { background: linear-gradient(135deg, #1A0D0D, #2B1414); }
    .work-card-8 .work-card-image { background: linear-gradient(135deg, #0D1A1A, #0A2020); }

    .work-card-body {
      padding: 1.5rem;
    }

    .work-card-client {
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--gray-500);
      margin-bottom: 0.625rem;
    }

    .work-card-title {
      font-size: 1.125rem;
      font-weight: 700;
      line-height: 1.3;
      color: var(--white);
      margin-bottom: 1rem;
    }

    .work-card-quote {
      font-size: 0.8125rem;
      color: var(--gray-500);
      line-height: 1.6;
      font-style: italic;
      margin-bottom: 1rem;
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .work-card-arrow {
      display: flex;
      align-items: center;
      gap: 0.375rem;
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      transition: color var(--transition), gap var(--transition);
    }
    .work-card:hover .work-card-arrow { color: var(--accent-hover); gap: 0.625rem; }

    /* ===== CTA BANNER ===== */
    #cta-banner {
      background: var(--white);
      color: var(--bg);
      padding: clamp(4rem, 8vw, 6rem) 0;
    }

    .cta-banner-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
      flex-wrap: wrap;
    }

    .cta-banner-text h2 {
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
      color: var(--bg);
      margin-bottom: 1rem;
    }

    .cta-banner-text p {
      font-size: 1.0625rem;
      color: var(--gray-700);
      max-width: 480px;
      line-height: 1.65;
    }

    .cta-banner-btn {
      background: var(--bg);
      color: var(--white);
      padding: 0.875rem 2rem;
      border-radius: var(--radius);
      font-size: 0.9375rem;
      font-weight: 700;
      letter-spacing: 0.02em;
      transition: var(--transition);
      flex-shrink: 0;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .cta-banner-btn:hover { background: #1A1A1A; transform: translateY(-2px); }

    /* ===== HOW WE WORK SECTION ===== */
    #how-we-work {
      background: var(--bg-1);
      padding: clamp(4rem, 8vw, 7rem) 0;
    }

    .how-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(2rem, 5vw, 5rem);
      align-items: center;
    }

    .how-visual {
      position: relative;
      aspect-ratio: 1;
      max-width: 520px;
    }

    .how-visual-circle {
      position: absolute;
      border-radius: 50%;
      border: 1px solid var(--border);
    }
    .how-visual-circle:nth-child(1) {
      inset: 0;
      background: linear-gradient(135deg, rgba(59,130,246,0.08) 0%, transparent 60%);
    }
    .how-visual-circle:nth-child(2) {
      inset: 15%;
      background: linear-gradient(135deg, rgba(245,158,11,0.06) 0%, transparent 60%);
    }
    .how-visual-circle:nth-child(3) {
      inset: 30%;
      background: var(--bg-card);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .how-visual-icon {
      font-size: 3rem;
      line-height: 1;
    }

    .how-text h2 {
      font-size: clamp(2rem, 3.5vw, 2.75rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
      margin-bottom: 1.5rem;
    }

    .how-text p {
      font-size: 1.0625rem;
      color: var(--gray-300);
      line-height: 1.7;
      margin-bottom: 2.5rem;
    }

    /* ===== INSIGHTS SECTION ===== */
    #insights {
      padding: clamp(4rem, 8vw, 7rem) 0;
    }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 1.25rem;
      margin-top: 2.5rem;
    }

    .insight-card {
      background: var(--bg-card);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: border-color var(--transition), transform var(--transition);
      cursor: pointer;
    }
    .insight-card:hover {
      border-color: var(--border-hover);
      transform: translateY(-3px);
    }

    .insight-card-img {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--bg-2);
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .insight-card:nth-child(1) .insight-card-img { background: linear-gradient(135deg, #0F1F35, #071428); }
    .insight-card:nth-child(2) .insight-card-img { background: linear-gradient(135deg, #1F0F35, #140728); }
    .insight-card:nth-child(3) .insight-card-img { background: linear-gradient(135deg, #0F3520, #071F12); }
    .insight-card:nth-child(4) .insight-card-img { background: linear-gradient(135deg, #35200F, #1F1007); }
    .insight-card:nth-child(5) .insight-card-img { background: linear-gradient(135deg, #1F350F, #121F07); }
    .insight-card:nth-child(6) .insight-card-img { background: linear-gradient(135deg, #350F1F, #1F0712); }
    .insight-card:nth-child(7) .insight-card-img { background: linear-gradient(135deg, #0F2035, #071428); }
    .insight-card:nth-child(8) .insight-card-img { background: linear-gradient(135deg, #35351A, #1F1F0A); }

    .insight-type-badge {
      position: absolute;
      top: 0.75rem;
      left: 0.75rem;
      font-size: 0.65rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      padding: 0.25rem 0.625rem;
      border-radius: 20px;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(4px);
    }

    .badge-podcast { color: var(--amber); border: 1px solid rgba(245,158,11,0.3); }
    .badge-article { color: var(--accent); border: 1px solid rgba(59,130,246,0.3); }
    .badge-report { color: #A78BFA; border: 1px solid rgba(167,139,250,0.3); }

    .insight-card-body {
      padding: 1.125rem;
    }

    .insight-card-title {
      font-size: 0.9375rem;
      font-weight: 700;
      line-height: 1.35;
      color: var(--white);
      margin-bottom: 1rem;
    }

    .insight-card-action {
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--accent);
      display: flex;
      align-items: center;
      gap: 0.25rem;
      transition: color var(--transition);
    }
    .insight-card:hover .insight-card-action { color: var(--accent-hover); }

    /* ===== PRINCIPLES SECTION ===== */
    #principles {
      background: var(--bg-1);
      padding: clamp(4rem, 8vw, 7rem) 0;
    }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 1.5px;
      background: var(--border);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      margin-top: 3rem;
    }

    .principle-item {
      background: var(--bg-card);
      padding: clamp(1.75rem, 3vw, 2.5rem);
      transition: background var(--transition);
    }
    .principle-item:hover { background: var(--bg-2); }

    .principle-number {
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      color: var(--accent);
      margin-bottom: 1rem;
    }

    .principle-title {
      font-size: 1.375rem;
      font-weight: 700;
      letter-spacing: -0.02em;
      margin-bottom: 0.875rem;
      line-height: 1.2;
    }

    .principle-body {
      font-size: 0.9375rem;
      color: var(--gray-300);
      line-height: 1.7;
    }

    /* ===== FOOTER ===== */
    footer {
      background: var(--bg-1);
      border-top: 1px solid var(--border);
    }

    .footer-ctas {
      display: grid;
      grid-template-columns: 1fr 1fr;
      border-bottom: 1px solid var(--border);
    }

    .footer-cta {
      padding: clamp(2.5rem, 5vw, 4rem) clamp(1.25rem, 4vw, 3rem);
      border-right: 1px solid var(--border);
      transition: background var(--transition);
    }
    .footer-cta:last-child { border-right: none; }
    .footer-cta:hover { background: var(--bg-2); }

    .footer-cta p {
      font-size: 1.0625rem;
      color: var(--gray-300);
      max-width: 360px;
      margin-bottom: 1.5rem;
      line-height: 1.65;
    }

    .footer-main {
      padding: 3rem clamp(1.25rem, 4vw, 3rem);
      display: grid;
      grid-template-columns: 1.5fr 1fr 1fr 1fr;
      gap: 2.5rem;
    }

    .footer-brand p {
      font-size: 0.9rem;
      color: var(--gray-500);
      line-height: 1.65;
      margin-top: 1rem;
      max-width: 280px;
    }

    .footer-col-title {
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--gray-500);
      margin-bottom: 1.25rem;
    }

    .footer-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }

    .footer-links a {
      font-size: 0.9rem;
      color: var(--gray-300);
      transition: color var(--transition);
    }
    .footer-links a:hover { color: var(--white); }

    .footer-bottom {
      border-top: 1px solid var(--border);
      padding: 1.5rem clamp(1.25rem, 4vw, 3rem);
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 1rem;
    }

    .footer-legal {
      font-size: 0.8125rem;
      color: var(--gray-500);
    }

    .footer-legal-links {
      display: flex;
      gap: 1.5rem;
      list-style: none;
      flex-wrap: wrap;
    }

    .footer-legal-links a {
      font-size: 0.8125rem;
      color: var(--gray-500);
      transition: color var(--transition);
    }
    .footer-legal-links a:hover { color: var(--gray-300); }

    /* ===== COOKIE CONSENT ===== */
    .cookie-banner {
      position: fixed;
      bottom: 1.5rem;
      left: 50%;
      transform: translateX(-50%) translateY(120px);
      width: calc(100% - 3rem);
      max-width: 880px;
      background: var(--bg-2);
      border: 1px solid var(--border-hover);
      border-radius: var(--radius-lg);
      padding: 1.5rem 2rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1.5rem;
      z-index: 500;
      transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
      flex-wrap: wrap;
      box-shadow: 0 24px 60px rgba(0,0,0,0.6);
    }
    .cookie-banner.visible { transform: translateX(-50%) translateY(0); }

    .cookie-text {
      flex: 1;
      min-width: 240px;
    }

    .cookie-text h4 {
      font-size: 0.9375rem;
      font-weight: 700;
      margin-bottom: 0.375rem;
    }

    .cookie-text p {
      font-size: 0.8125rem;
      color: var(--gray-300);
      line-height: 1.5;
    }

    .cookie-text a {
      color: var(--accent);
      text-decoration: underline;
    }

    .cookie-actions {
      display: flex;
      gap: 0.75rem;
      flex-wrap: wrap;
    }

    .cookie-btn {
      padding: 0.5625rem 1.125rem;
      font-size: 0.8125rem;
      font-weight: 600;
      border-radius: var(--radius);
      transition: var(--transition);
      cursor: pointer;
      font-family: var(--font);
    }

    .cookie-btn-accept {
      background: var(--white);
      color: var(--bg);
      border: 1px solid var(--white);
    }
    .cookie-btn-accept:hover { background: var(--gray-100); }

    .cookie-btn-manage {
      background: transparent;
      color: var(--gray-300);
      border: 1px solid var(--border-hover);
    }
    .cookie-btn-manage:hover { color: var(--white); border-color: var(--white); }

    .cookie-btn-decline {
      background: transparent;
      color: var(--gray-500);
      border: none;
      padding-left: 0.5rem;
      padding-right: 0.5rem;
    }
    .cookie-btn-decline:hover { color: var(--gray-300); }

    /* ===== SCROLL INDICATOR ===== */
    .scroll-progress {
      position: fixed;
      top: 64px;
      left: 0;
      height: 2px;
      background: var(--accent);
      z-index: 99;
      transition: width 0.1s;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .team-card {
        width: calc((100% - 1.5rem) / 2);
      }
      .insights-grid {
        grid-template-columns: repeat(3, 1fr);
      }
      .how-inner {
        grid-template-columns: 1fr;
      }
      .how-visual { display: none; }
      .footer-main {
        grid-template-columns: 1fr 1fr;
      }
    }

    @media (max-width: 768px) {
      .nav-links, .nav-contact-btn { display: none; }
      .nav-hamburger { display: flex; }

      .hero-inner { flex-direction: column; align-items: flex-start; }
      .hero-controls { flex-direction: row; }
      .hero-dots { flex-direction: row; }
      .hero-dot { width: 20px; height: 3px; }
      .hero-dot.active { width: 40px; height: 3px; }

      .team-card { width: 85vw; max-width: 340px; }

      .work-card { width: 80vw; min-width: 280px; }

      .cta-banner-inner { flex-direction: column; gap: 2rem; }

      .insights-grid { grid-template-columns: repeat(2, 1fr); }

      .principles-grid { grid-template-columns: 1fr; }

      .footer-ctas { grid-template-columns: 1fr; }
      .footer-cta { border-right: none; border-bottom: 1px solid var(--border); }
      .footer-cta:last-child { border-bottom: none; }
      .footer-main { grid-template-columns: 1fr 1fr; }
      .footer-bottom { flex-direction: column; align-items: flex-start; }
    }

    @media (max-width: 480px) {
      .insights-grid { grid-template-columns: 1fr; }
      .footer-main { grid-template-columns: 1fr; }
    }

    /* ===== UTILITY ===== */
    .visually-hidden {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border-width: 0;
    }

    .mt-auto { margin-top: auto; }

    /* ===== ANIMATIONS ===== */
    @keyframes fadeUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .fade-up {
      opacity: 0;
      animation: fadeUp 0.7s cubic-bezier(0.4, 0, 0.2, 1) forwards;
    }

    .fade-up-delay-1 { animation-delay: 0.1s; }
    .fade-up-delay-2 { animation-delay: 0.2s; }
    .fade-up-delay-3 { animation-delay: 0.3s; }
  </style>
</head>
